<?php
declare(strict_types=1);
require_once __DIR__ . '/_bootstrap.php';
require_once __DIR__ . '/_layout.php';
$msg='';$erro='';$testCharge=null;
$cfg=reseller_pagbank_load_config($pdo,RESELLER_COMPANY_ID);
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  $action=(string)($_POST['action']??'save');
  if($action==='save'){$cfg=reseller_pagbank_save_config($pdo,RESELLER_COMPANY_ID,$_POST);$msg='Configurações do PagBank salvas.';}
  elseif($action==='test_charge'){
    $clientId=(int)($_POST['client_company_id']??0);$amount=reseller_money_value($_POST['amount']??0);
    if($clientId<=0||$amount<=0)throw new RuntimeException('Selecione o cliente e informe um valor para o teste.');
    $st=$pdo->prepare('SELECT id FROM companies WHERE id=? AND reseller_company_id=? LIMIT 1');$st->execute([$clientId,RESELLER_COMPANY_ID]);if(!$st->fetchColumn())throw new RuntimeException('Cliente inválido.');
    $pdo->prepare("INSERT INTO saas_reseller_customer_charges (reseller_company_id,client_company_id,origin,description,amount,due_date,status) VALUES (?,?,'manual','Cobrança de teste PagBank',?,?, 'open')")->execute([RESELLER_COMPANY_ID,$clientId,$amount,date('Y-m-d',strtotime('+1 day'))]);
    $chargeId=(int)$pdo->lastInsertId();$method=(string)($_POST['method']??'pix');$testCharge=reseller_pagbank_create_charge($pdo,RESELLER_COMPANY_ID,$chargeId,$method);$msg=$method==='card'?'Checkout de cartão de teste criado.':'Cobrança Pix de teste criada.';
  }
 }catch(Throwable $e){$erro=$e->getMessage();}
}
$cfg=reseller_pagbank_load_config($pdo,RESELLER_COMPANY_ID);
$clients=reseller_client_companies($pdo,RESELLER_COMPANY_ID);
$rows=[];try{$st=$pdo->prepare("SELECT ch.*,c.name AS client_name FROM saas_reseller_customer_charges ch INNER JOIN companies c ON c.id=ch.client_company_id WHERE ch.reseller_company_id=? AND ch.payment_gateway='pagbank' ORDER BY ch.id DESC LIMIT 20");$st->execute([RESELLER_COMPANY_ID]);$rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){}
$webhook=(string)$cfg['webhook_url'];if($webhook==='')$webhook=current_scheme().'://'.current_host_name().'/webhooks/reseller_pagbank.php';$webhook.=(str_contains($webhook,'?')?'&':'?').'reseller='.RESELLER_COMPANY_ID.'&token='.rawurlencode((string)$cfg['webhook_token']);
revenda_layout_start('PagBank da revenda','pagbank',$reseller);
?>
<?php if($msg):?><div class="ok"><?=rev_h($msg)?></div><?php endif;?><?php if($erro):?><div class="err"><?=rev_h($erro)?></div><?php endif;?>
<div class="grid2"><div class="panel"><h2>Credenciais do PagBank</h2><p class="muted">Esta configuração pertence somente à revenda. As cobranças dos seus clientes serão recebidas nesta conta.</p><form method="post"><input type="hidden" name="action" value="save"><label>Ambiente<select name="environment"><option value="sandbox" <?=$cfg['environment']==='sandbox'?'selected':''?>>Sandbox / testes</option><option value="production" <?=$cfg['environment']==='production'?'selected':''?>>Produção</option></select></label><label>Token PagBank<input name="token" value="<?=rev_h((string)$cfg['token'])?>" autocomplete="off"></label><div class="grid2"><label>Expiração do Pix em minutos<input type="number" min="5" max="43200" name="pix_expiration_minutes" value="<?=(int)$cfg['pix_expiration_minutes']?>"></label><label>Máximo de parcelas<input type="number" min="1" max="18" name="max_installments" value="<?=(int)$cfg['max_installments']?>"></label></div><label>Identificação na cobrança<input name="soft_descriptor" maxlength="17" value="<?=rev_h((string)$cfg['soft_descriptor'])?>"></label><label>URL personalizada do webhook (opcional)<input name="webhook_url" value="<?=rev_h((string)$cfg['webhook_url'])?>"></label><label>Token interno do webhook<input name="webhook_token" value="<?=rev_h((string)$cfg['webhook_token'])?>"></label><div class="grid2"><label style="display:flex;gap:9px;align-items:center"><input type="checkbox" name="pix_enabled" value="1" <?=!empty($cfg['pix_enabled'])?'checked':''?>> Habilitar Pix</label><label style="display:flex;gap:9px;align-items:center"><input type="checkbox" name="card_enabled" value="1" <?=!empty($cfg['card_enabled'])?'checked':''?>> Habilitar cartão</label></div><label style="display:flex;gap:9px;align-items:center"><input type="checkbox" name="active" value="1" <?=!empty($cfg['active'])?'checked':''?>> Ativar PagBank da revenda</label><div class="actions"><button class="btn btn-primary">Salvar integração</button></div></form></div>
<div class="panel"><h2>Webhook</h2><p class="muted">Cadastre este endereço nas notificações da conta PagBank da revenda:</p><textarea rows="4" readonly><?=rev_h($webhook)?></textarea><h2 style="margin-top:20px">Gerar cobrança de teste</h2><form method="post"><input type="hidden" name="action" value="test_charge"><label>Forma de pagamento<select name="method"><option value="pix">Pix</option><option value="card">Cartão / checkout</option></select></label><label>Cliente<select name="client_company_id" required><option value="">Selecione</option><?php foreach($clients as $c):?><option value="<?=(int)$c['id']?>"><?=rev_h((string)$c['name'])?></option><?php endforeach;?></select></label><label>Valor<input name="amount" value="1,00"></label><div class="actions"><button class="btn btn-primary">Criar cobrança de teste</button></div></form><?php if($testCharge):?><div class="ok" style="margin-top:14px">Link criado: <a target="_blank" href="<?=rev_h((string)$testCharge['payment_url'])?>"><?=rev_h((string)$testCharge['payment_url'])?></a></div><?php endif;?></div></div>
<div class="panel" style="margin-top:16px"><h2>Últimas cobranças PagBank</h2><div class="table"><table><thead><tr><th>Cliente</th><th>Forma</th><th>Valor</th><th>Vencimento</th><th>Status</th><th>Referência</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=rev_h((string)$r['client_name'])?></td><td><?=rev_h(strtoupper((string)($r['payment_method']??'PIX')))?></td><td><?=rev_money((float)$r['amount'])?></td><td><?=rev_h(rev_date_br($r['due_date']))?></td><td><span class="pill"><?=rev_h((string)($r['gateway_status']?:$r['status']))?></span></td><td><?=rev_h((string)$r['gateway_reference'])?></td><td><?php if(!empty($r['payment_url'])):?><a class="btn btn-ghost" target="_blank" href="<?=rev_h((string)$r['payment_url'])?>">Abrir</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">Nenhuma cobrança PagBank criada.</td></tr><?php endif;?></tbody></table></div></div>
<?php revenda_layout_end(); ?>
